create table public.hr_candidates (id uuid default gen_random_uuid(),vacancy_id uuid,full_name text,whatsapp text,email text,municipality text,availability boolean,compensation_accepted boolean,start_availability text,experience_range text,relevant_areas text[] default '{}'::text[],tools text[] default '{}'::text[],excel_level text,driving_license boolean,external_errands boolean,transport_modes text[] default '{}'::text[],status text default 'new'::text,source text default 'public_form'::text,submitted_at timestamp with time zone default now(),decision_status text,decision_note text,profiled_target_role text,profiled_at timestamp with time zone,decision_updated_at timestamp with time zone,recruitment_cycle_id uuid,interview_availability_confirmed_at timestamp with time zone,internal_first_impression text,internal_role_fit text,internal_strengths text,internal_interview_checks text,internal_notes text);
create table public.hr_employees (id uuid default gen_random_uuid(),candidate_id uuid,role_id uuid,vacancy_id uuid,full_name text,email text,whatsapp text,role_title text,status text default 'active'::text,hired_at timestamp with time zone default now(),system_username text,system_auth_user_id uuid,system_roles jsonb default '[]'::jsonb,access_notes text,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now(),system_access_enabled boolean default false);
create table public.hr_hiring_cases (trial_id uuid,candidate_id uuid,role_id uuid,token_hash text,expires_at timestamp with time zone,revoked_at timestamp with time zone,data jsonb default '{}'::jsonb,inherited_documents jsonb default '{}'::jsonb,contract jsonb,revision integer default 0,submitted_at timestamp with time zone,notified_at timestamp with time zone,verified_at timestamp with time zone,signed_at timestamp with time zone,employee_id uuid,created_at timestamp with time zone default now(),confirmed_fields text[] default '{}'::text[]);
create table public.inventory_products (id uuid default gen_random_uuid(),name text,category text,unit text,description text default ''::text,currency text,stock numeric default 0,unit_cost numeric default 0,minimum_stock numeric default 0,created_at timestamp with time zone default now(),photo_path text,reference_cost numeric,location text,updated_at timestamp with time zone default now());
create table public.system_access_roles (id uuid default gen_random_uuid(),code text,title text,area text,reports_to_code text,description text default ''::text,is_active boolean default true,created_at timestamp with time zone default now(),updated_at timestamp with time zone default now());
create table public.system_employee_role_assignments (id uuid default gen_random_uuid(),employee_id uuid,access_role_id uuid,assigned_at timestamp with time zone default now(),ended_at timestamp with time zone,notes text,created_at timestamp with time zone default now());
