create table studio_access_private.onboarding (candidate_id uuid,employee_id uuid,role_id uuid,configured_at timestamp with time zone default now(),created_at timestamp with time zone,whatsapp_opened_at timestamp with time zone,activated_at timestamp with time zone,token_hash text,token_cipher text,expires_at timestamp with time zone,lease uuid,lease_until timestamp with time zone,email_requested_at timestamp with time zone,message text,route_reopened_at timestamp with time zone,route_configured_at timestamp with time zone,route_prepared_at timestamp with time zone,pending_email text);
